function counterReducer(state = 0, action) {
  switch (action.type) {
    case 'counter/incremented': return state + 1;
    default: return state;
  }
}

// Wrong: state.count++
// Right:
return { ...state, count: state.count + 1 };

function todosReducer(state = [], action) {
  switch (action.type) {
    case 'todos/added':
      return [...state, action.payload];
    default:
      return state;
  }
}
